    automationLevel: "Automatisierungsgrad", manual: "Manuell", semiAuto: "Teilautomatisch", fullAuto: "Vollautomatisch", featurePrAutomerge: "Feature-PR automatisch mergen", mainPrAutomerge: "Main-PR automatisch mergen", off: "Aus", createPr: "PR erstellen", whenGreen: "Bei erfolgreichen Checks", always: "Immer", autoApprovePlans: "Pläne automatisch genehmigen", autoApprovePlansBody: "Die Planung ohne manuelle Genehmigung fortsetzen, sobald der erstellte Plan verfügbar ist.", memorySystem: "Speichersystem", memorySystemBody: "Erkenntnisse aus Sprints und Agenten zur späteren Nutzung erfassen.", resolveMainConflicts: "Main-Merge-Konflikte beheben", resolveMainConflictsBody: "Vor einer Eskalation einen virtuellen Worker Konflikte am Main-Branch-Merge-Gate bearbeiten lassen.", fixMainCi: "CI-Fehler beim Main-Merge beheben", fixMainCiBody: "Vor einer Eskalation einen virtuellen Worker fehlgeschlagene CI-Prüfungen am Main-Branch-Merge-Gate beheben lassen.", resolveFeatureConflicts: "Feature-Merge-Konflikte beheben", resolveFeatureConflictsBody: "Einen virtuellen Worker sichere Feature-PR-Konflikte mit dem Sprint-Branch beheben lassen.", enableQaAgent: "QA-Agent aktivieren", enableQaAgentBody: "Nach Aufgaben- und Sprintabschluss Qualitätsprüfungen ausführen.",
    defaultConfiguration: "Standardkonfiguration", defaultConfigurationBody: "Lege fest, welche Anbieterinstanzen bestimmte Rollen für neue Projekte übernehmen.", pickDefaultProviders: "Standardanbieter auswählen", pickDefaultProvidersBody: "Wähle die Instanz für Standardantworten und die Instanz, die virtuelle Worker in Containern verwenden. Das Routing je Route kann später auf der Seite KI-Modelle angepasst werden.", noEnabledProviders: "Noch keine Anbieter aktiviert. Gehe zu Anbieter auswählen und Anbieter zurück, um mindestens eine Instanz zu aktivieren.", defaultRouting: "Standardrouting", defaultPrimaryProvider: "Primärer Standardanbieter", defaultPrimaryProviderBody: "Die primäre Intelligenz-Engine für allgemeine Aufgaben.", defaultCliWorkerProvider: "Standardanbieter für CLI-Worker", defaultCliWorkerProviderBody: "Die Engine für CLI-Hintergrundaufgaben; sie muss Werkzeugausführung unterstützen.", defaultAiProvider: "Standard-KI-Anbieter", defaultAiProviderBody: "Die Instanz für Routen ohne ausdrückliche Überschreibung.", virtualWorkerProvider: "Anbieter für virtuelle Worker", virtualWorkerProviderBody: "Die CLI-Instanz, die zum Ausführen von Aufgaben in Docker-Container gesendet wird.", selectedInstancesOverview: "Übersicht ausgewählter Instanzen", defaultBadge: "Standard", workerBadge: "Worker", availableBadge: "Verfügbar",
