export type OnboardingMessageKey = DashboardTextMessageKey<typeof onboardingMessages>;
export type OnboardingPluralMessageKey = DashboardPluralMessageKey<typeof onboardingMessages>;

export const translateOnboardingMessage = (
  locale: DashboardLocale,
  key: OnboardingMessageKey,
  variables?: DashboardMessageVariables,
): string => translateDashboardMessage(onboardingMessages, locale, key, variables);

export const useOnboardingMessages = () => {
  const { locale, translate, translatePlural } = useDashboardI18n();
  const t = useCallback((key: OnboardingMessageKey, variables?: DashboardMessageVariables): string => (
    translate(onboardingMessages, key, variables)
  ), [translate]);
  const tp = useCallback((key: OnboardingPluralMessageKey, count: number, variables?: DashboardMessageVariables): string => (
    translatePlural(onboardingMessages, key, count, variables)
  ), [translatePlural]);
  return { locale, t, tp };
};
